ctx='arn:aws:eks:us-east-2:753556437180:cluster/phorvex-dev-eks'
root=Path('/home/hami/phorvex-benchmark')
out=root/'stage-data/live/selfserve-capture';out.mkdir(parents=True,exist_ok=True)
def run(args,**kw):
 return subprocess.run(args,capture_output=True,text=True,check=True,timeout=40,**kw)
def get(kind,name,ns):return json.loads(run(['kubectl','--context',ctx,'-n',ns,'get',kind,name,'-o','json','--request-timeout=20s']).stdout)
def save(name,obj):
 p=out/name;p.write_text(json.dumps(obj,indent=2)+'\n');os.chmod(p,0o600)
assert shutil.disk_usage(root).free > 4*1024**3
app=get('applicationset','phorvex-services','argocd')
assert app['metadata']['uid']==payload['operation']['expected_uid']
assert app['spec']==payload['expected']['appset_spec'], 'ApplicationSet changed since reviewed proposal'
assert app['spec'].get('templatePatch') is None
for old in payload['expected']['deployments']:
 d=get('deployment',old['name'],'phorvex-staging')
 assert d['metadata']['uid']==old['uid'] and d['metadata']['generation']==old['generation'], 'Deployment changed since review'
 assert [{k:c.get(k,[]) for k in ['name','image','args']} for c in d['spec']['template']['spec']['containers']]==old['containers']
 assert d['status'].get('observedGeneration')==d['metadata']['generation'], 'Unobserved initial generation'
 assert all(d['status'].get(k,0)==d['spec'].get('replicas',1) for k in ['readyReplicas','updatedReplicas','availableReplicas','replicas']), 'Incomplete initial rollout'
 assert all(x.get('status')=='True' for x in d['status'].get('conditions',[]) if x['type'] in ['Available','Progressing']), 'Unhealthy initial rollout'
for old in payload['expected']['policies']:
 p=get('phorvexpolicy',old['name'],'phorvex-staging-demo')
 assert p['metadata']['uid']==old['uid'] and p['metadata']['generation']==old['generation'] and p['spec'].get('mode')==old['mode']
for component in ['brain','manager','console']:
 a=get('application','phorvex-'+component+'-staging','argocd')
 assert a.get('status',{}).get('health',{}).get('status')=='Healthy', 'Initial application not Healthy'
 assert a.get('status',{}).get('operationState',{}).get('phase')=='Succeeded', 'Initial application operation incomplete'
